from pathlib import Path
import json
r=Path('drafts/catalog-074/overview'); d=r/'diagrams'; d.mkdir(parents=True,exist_ok=True)
inv=json.loads(Path('coordination/catalog-074/inventory.json').read_text()); ms=inv['manuscripts']
sources={'catalogId':'074','checkedOn':'2026-10-16','externalSources':[{**m,'id':m['citationKey'],'checkedLocations':[{'printedPage':str(p),'pdfPage':p} for p in ([2,20,21,32,33,35,36,37,38,86,87,88,89,90,91,92,93,94] if m['order']==1 else [3,17,18,20,21,22,23,24,25,168])]} for m in ms]}
(r/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n')
cites={}
for id,key,result,pages in [('three-main','OpenAI26a','Theorem 1.1','2'),('three-plank','OpenAI26a','Lemma 3.3','20–21'),('three-use','OpenAI26a','Lemmas 4.7, 4.9','32–33, 35–38'),('three-end','OpenAI26a','Section 10','86–94'),('four-main','OpenAI26b','Theorem 1.1','3'),('four-plank','OpenAI26b','Lemma 2.15','17–18'),('four-reduction','OpenAI26b','Theorem 2.17','20–25'),('four-end','OpenAI26b','Section 10.8','168'),('catalogue','OVERVIEW','074','9')]:
 cites[id]={'source':key,'locations':[{'result':result,'printed':pages,'pdf':pages}]}
reg={'schemaVersion':1,'citationStyle':'author-key','catalogId':'074','sources':{m['citationKey']:{'recordFile':'sources.json','recordId':m['citationKey'],'pagination':'same'} for m in ms},'citations':cites,'markdownFiles':['article.ja.md','article.en.md'],'diagramDirectories':['diagrams']}
reg['sources']['OVERVIEW']={'recordFile':'../../../coordination/catalog-074/inventory.json','recordId':'overview'}
(r/'citations.json').write_text(json.dumps(reg,ensure_ascii=False,indent=2)+'\n')
rows=[]
claims=[{'ja':'すべての ε>0 と 0<δ<1 に対し、単位長・半径δのチューブ最大作用素が L³(ℝ³)→L³(S²)、ノルム Cε δ⁻ε。','en':'For every ε>0 and 0<δ<1, the maximal operator over unit tubes of radius δ maps L³(ℝ³) to L³(S²) with norm Cε δ⁻ε.'},{'ja':'各方向に単位線分を含む任意の K⊂ℝ⁴ は Hausdorff次元4。集合にも線分の選択にも可測性・コンパクト性を仮定しない。','en':'Every K⊂ℝ⁴ containing a unit segment in each direction has Hausdorff dimension four, without measurability or compactness assumptions on K or its witnesses.'}]
roles=[{'ja':'密度依存を保つ重み付き配置と定常極値配置の排除から最大関数へ。独立のplank補題が4Dの帰着にも使われる。','en':'Weighted configurations retain density dependence; exclusion of stationary extremizers yields the maximal bound. A separate plank lemma also enters the 4D reduction.'},{'ja':'可変尺度被覆から正のhorizonを持つ重み付き問題へ帰着し、三つの配置で改善を構成して矛盾させる。','en':'Variable-scale covers yield a weighted problem with positive horizon; improvements in three geometric regimes contradict extremality.'}]
for i,m in enumerate(ms): rows.append({'paperId':m['paperId'],'displayName':m['displayName'],'result':'Theorem 1.1 · p. '+('2' if i==0 else '3'),'claim':claims[i],'role':roles[i]})
(r/'presentation.json').write_text(json.dumps({'schemaVersion':1,'checkedOn':'2026-10-16','rows':rows},ensure_ascii=False,indent=2)+'\n')
def cite(id):return '<!-- cite:'+id+' -->generated<!-- /cite -->'
for lang in ['ja','en']:
 ja=lang=='ja'
 lead=('三次元では最大関数の密度依存、四次元では任意集合のHausdorff次元を扱う。両者をつなぐのは三次元原稿内の重み付きplank補題であり、最大関数定理そのものではない。' if ja else 'The three-dimensional paper addresses density dependence in a maximal estimate; the four-dimensional paper treats Hausdorff dimension for arbitrary sets. Their recorded connection is a weighted plank lemma in the three-dimensional paper, rather than its maximal theorem.')
 txt='# '+inv['overviewTitle']+'\n\n**'+('三次元と四次元のKakeya問題' if ja else 'Two conclusions and one result-level input')+'**\n\n'+lead+'\n\n'
 txt+='<!-- Stage 2: insert actual bilingual booklet PDF links before the inventory; no PDF exists in Stage 1. -->\n\n## 1. '+('公式順の記事一覧' if ja else 'Papers in official catalogue order')+'\n\nCATALOGINVENTORYTOKEN\n\n'
 txt+='## '+('図の矢印に付した引用' if ja else 'References on the arrows')+'\n\n'
 txt+=('この案内では、以下の著者由来キーを使う。原稿の主張と編集側の照合範囲を区別する。\n\n' if ja else 'This guide uses the author-derived keys below and distinguishes manuscript claims from the editorial checking scope.\n\n')
 for m in ms:txt+=f"- **{m['citationKey']}** — OpenAI, *{m['title']}*, {m['version']}. "+('用途：' if ja else 'Role: ')+roles[m['order']-1][lang]+' '+cite('three-main' if m['order']==1 else 'four-main')+'\n'
 txt+='\n## 2. '+('二つの結論と、共有されるplank入力' if ja else 'Two conclusions and the shared plank input')+'\n\n'
 txt+=('図は主要な接続をまとめたもので、各矢印に書いた補題だけで主定理が従うという意味ではない。追加の幾何入力と反復の条件は個別記事で示す。\n\n' if ja else 'The diagram records the principal connection, not a deduction of either main theorem from the displayed lemma alone. The articles explain the additional geometric inputs and conditions on iteration.\n\n')
 txt+='!['+('最大関数評価とHausdorff次元の異なる経路' if ja else 'Distinct routes to the maximal estimate and Hausdorff dimension')+f'](diagrams/routes.{lang}.svg)\n\n'
 txt+=('三次元側では、全時間のplank集中を制御する重み付き評価を、flat scaleでのplate捕捉と正のdeficitを持つ配置の構成に使う。主結果へは定常配置の排除に加え、離散評価から一般の $L^3$ 関数への移行が必要であり、集合の体積下界だけで最大関数評価を代用しない。\n\n' if ja else 'On the three-dimensional side, the weighted full-time plank estimate supplies plate capture at a flat scale and configurations with positive deficit. The main theorem additionally requires exclusion of stationary configurations and the passage from discrete estimates to general $L^3$ functions; a set-volume bound alone does not replace that passage.\n\n')+cite('three-use')+' '+cite('three-end')+'\n\n'
 txt+=('四次元側では、同型の重み付きplank評価をLemma 2.15として用い、Hausdorff反例を正のhorizonを持つ重み付き問題へ移す。その後の配置別の改善と元の尺度への回収は四次元原稿の議論である。結論は $\\dim_H K=4$ であり、四次元の最大関数評価はここでは主張しない。\n\n' if ja else 'On the four-dimensional side, the matching weighted plank estimate is used as Lemma 2.15 in the reduction from a Hausdorff counterexample to a weighted problem with positive horizon. The subsequent geometric improvements and recovery at the original scale belong to the four-dimensional argument. The conclusion is $\\dim_H K=4$; this guide makes no four-dimensional maximal-operator claim.\n\n')+cite('four-reduction')+' '+cite('four-end')+'\n\n'
 txt+=('**引用番号の照合。** 四次元原稿は入力を [24, Lemma 2.3] と記す。今回固定した三次元版では、対応する全時間plankの仮定・長いmark条件・結論はLemma 3.3にある。この内容対応を照合したが、番号が変わった版履歴は未確認である。利用先の番号を黙って修正せず、この差を保持する。\n\n' if ja else '**Citation-number check.** The four-dimensional manuscript cites [24, Lemma 2.3]. In the pinned three-dimensional version, the corresponding full-time plank hypothesis, long-mark condition, and conclusion occur in Lemma 3.3. These interfaces were compared, but the revision history explaining the changed number has not been checked. We retain this discrepancy rather than silently rewriting the receiving citation.\n\n')+cite('three-plank')+' '+cite('four-plank')+'\n\n'
 txt+=('詳細は[三次元の記事](../kakeya-maximal-three/article.ja.md)と[四次元の記事](../kakeya-hausdorff-four/article.ja.md)へ。' if ja else 'See the [three-dimensional article](../kakeya-maximal-three/article.en.md) and the [four-dimensional article](../kakeya-hausdorff-four/article.en.md) for the conditions and proof steps.')+'\n\n'
 txt+='## 3. '+('原典・確認範囲' if ja else 'Sources and checking scope')+'\n\n'
 txt+=('公式分野は **Real and complex analysis**（実解析・複素解析、071–086）。本カタログは概要PDF p.9にあり、公式順の2本を掲載する。' if ja else 'The official subject is **Real and complex analysis** (071–086). This catalogue appears on overview PDF p.9; the two papers are listed in official order.')+'\n\n'+cite('catalogue')+'\n\n'
 txt+=('参照commitは `'+inv['sourceCommit']+'`。主結果、選んだ証明本文、直接入力の記述と使用箇所を照合した。全97頁・175頁の証明を独立に検証したものではなく、各記事末尾に未確認箇所を明記する。他カタログとの未掲載の接続は未調査であり、依存なしを意味しない。\n' if ja else 'The source commit is `'+inv['sourceCommit']+'`. The main statements, selected proof passages, and statements and applications of direct inputs were compared. This is not an independent verification of the complete 97- and 175-page proofs; each article identifies unchecked passages. Unlisted connections with other catalogues remain uninvestigated, not absent.\n')
 (r/f'article.{lang}.md').write_text(txt)
